Object.assign(EX,{
writing:{m:['Первые таблички из Урука были учётными: на них записывали зерно, скот и пиво. Позднее знаки стали передавать звуки языка. Египетские иероглифы появились примерно в то же время, а китайское письмо известно по гадательным костям около 1200 г. до н.э.','The first tablets from Uruk were accounting records of grain, livestock and beer. Later the signs came to represent sounds of speech. Egyptian hieroglyphs appeared at about the same time, and Chinese writing is known from oracle bones of around 1200 BC.'],f:[['«Эпос о Гильгамеше» — одно из древнейших литературных произведений мира.','The Epic of Gilgamesh is one of the oldest works of literature in the world.']]},
athens:{m:['Клисфен разделил жителей Аттики на десять фил и создал Совет пятисот. Высшей властью было Народное собрание. Расцвет демократии связан с Периклом в V в. до н.э.','Cleisthenes divided the people of Attica into ten tribes and created the Council of Five Hundred. The Assembly held supreme power. Democracy flourished under Pericles in the 5th century BC.'],f:[['Остракизм: чтобы изгнать человека на десять лет, нужно было не менее 6000 голосов, записанных на глиняных черепках.','Ostracism: to exile a man for ten years at least 6,000 votes were needed, scratched on pottery shards.']]},
crusades:{m:['Первый поход (1096–1099) завершился взятием Иерусалима. В 1187 г. Саладин вернул город, а Третий поход, в котором участвовал Ричард Львиное Сердце, закончился перемирием 1192 г. Последний оплот крестоносцев, Акра, пал в 1291 г.','The First Crusade (1096–1099) ended with the capture of Jerusalem. In 1187 Saladin retook the city, and the Third Crusade, which included Richard the Lionheart, ended in a truce in 1192. The last crusader stronghold, Acre, fell in 1291.'],f:[['Четвёртый поход (1202–1204) закончился разграблением христианского Константинополя.','The Fourth Crusade (1202–1204) ended with the sack of Christian Constantinople.']]},
blackdeath:{m:['Чума пришла в Европу в 1347 г. через порты Крыма и Сицилии и к 1351 г. охватила почти весь континент. Города вводили карантины, а вспышки возвращались десятилетиями. Нехватка рабочих рук улучшила положение крестьян.','The plague reached Europe in 1347 via ports in Crimea and Sicily and covered nearly the whole continent by 1351. Cities introduced quarantines and outbreaks returned for decades. Labour shortages improved the position of peasants.'],f:[['Слово «карантин» происходит от итальянского «сорок дней».','The word “quarantine” comes from the Italian for “forty days”.']]},
printing:{m:['Первой крупной печатной книгой стала 42-строчная Библия (около 1455 г.). К 1500 г. в Европе было напечатано, по оценкам, свыше 20 млн экземпляров. Подвижные литеры использовали в Китае и Корее и раньше.','The first major printed book was the 42-line Bible (c. 1455). By 1500 more than 20 million copies had been printed in Europe, by some estimates. Movable type had been used earlier in China and Korea.'],f:[['Старейшая сохранившаяся книга, напечатанная металлическими литерами, — корейский «Чикчи» (1377).','The oldest surviving book printed with metal type is Korea’s Jikji (1377).']]},
moon:{m:['Лунный модуль «Игл» сел в Море Спокойствия 20 июля 1969 г. Армстронг и Олдрин провели вне модуля около двух с половиной часов и собрали около 21,5 кг образцов, а Майкл Коллинз ждал на орбите. Всего на Луне в 1969–1972 гг. побывали 12 человек.','The lunar module Eagle landed in the Sea of Tranquility on 20 July 1969. Armstrong and Aldrin spent about two and a half hours outside and collected about 21.5 kg of samples while Michael Collins waited in orbit. In total 12 people walked on the Moon between 1969 and 1972.'],f:[['Управляющий компьютер «Аполлона» имел около 4 КБ оперативной памяти.','The Apollo guidance computer had about 4 KB of erasable memory.']]}});
FACTS.push(['Слово «карантин» происходит от итальянского «сорок дней» — срока изоляции во времена чумы.','The word “quarantine” comes from the Italian for “forty days”, the isolation period in plague times.'],['Названия месяцев сентябрь–декабрь означают «седьмой–десятый»: в римском календаре год начинался в марте.','September to December mean “seventh” to “tenth”: in the Roman calendar the year began in March.'],['Империя, созданная Чингисханом и его потомками, стала крупнейшей непрерывной сухопутной империей в истории.','The empire built by Genghis Khan and his descendants was the largest contiguous land empire in history.'],['Мария Кюри — единственный человек с Нобелевскими премиями в двух разных естественных науках.','Marie Curie is the only person to win Nobel Prizes in two different natural sciences.'],['Римляне называли Средиземное море «Наше море» (Mare Nostrum).','The Romans called the Mediterranean “Our Sea” (Mare Nostrum).']);
DAYS.push([7,20,'1969 г. — «Аполлон-11» высаживается на Луну.','1969 — Apollo 11 lands on the Moon.'],[11,7,'1867 г. — родилась Мария Кюри.','1867 — Marie Curie is born in Warsaw.'],[4,21,'1926 г. — родилась Елизавета II.','1926 — Elizabeth II is born in London.'],[2,12,'1809 г. — родился Авраам Линкольн.','1809 — Abraham Lincoln is born.'],[9,23,'63 до н.э. — родился Август (Октавиан).','63 BC — Augustus (Octavian) is born.']);

/* ---------- helpers ---------- */
const $=s=>document.querySelector(s), app=$('#app');
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const initials=p=>esc(L(p.n).split(' ').map(w=>w[0]).slice(0,2).join(''));
const portrait=p=>`<img class="ph" loading="lazy" src="${p.img?W(p.img):'data:,'}" data-wp="${WP[p.id]}" alt="${esc(L(p.n))}" data-fb="${initials(p)}">`;
document.addEventListener('error',async e=>{const i=e.target;if(i.tagName!=='IMG'||!i.dataset.fb)return;if(i.dataset.wp){const c=await cands(i.dataset.wp),n=+(i.dataset.n||0);if(n<c.length){i.dataset.n=n+1;i.src=c[n];return}}const d=document.createElement('div');d.className='fb'+(i.classList.contains('ev')?' ev':'');d.textContent=i.dataset.fb;i.replaceWith(d)},true);
const personCard=p=>`<a class="card" href="#/person/${p.id}">${portrait(p)}<div class="b"><h3>${esc(L(p.n))}</h3><small>${esc(L(p.c))} · ${esc(L(p.dt).split(/ — | – /)[0])}</small></div></a>`;
const eventCard=e=>`<a class="card" href="#/event/${e.id}">${evPic(e)}<div class="b"><span class="tag">${esc(L(e.dt))}</span><h3>${esc(L(e.n))}</h3><p class="meta">${esc(L(e.d).slice(0,110))}…</p></div></a>`;
const srcList=s=>`<h3>${t('src')}</h3><ul>${s.map(x=>`<li><a href="${x[1]}" target="_blank" rel="noopener">${esc(x[0])}</a></li>`).join('')}</ul>`;
const todayItem=()=>{const n=new Date(),k=(n.getMonth()+1)*100+n.getDate();let d=DAYS.find(x=>x[0]*100+x[1]===k);const exact=!!d;if(!d)d=DAYS.find(x=>x[0]*100+x[1]>k)||DAYS[0];return{d,exact}};

/* ---------- pages ---------- */
function home(){const {d,exact}=todayItem(),rnd=FACTS.map(f=>`<li>${esc(L(f))}</li>`).join('');
return`<section class="hero fade"><div><h1>${t('h1')}</h1><p>${t('lead')}</p><a class="btn" href="#/people">${t('cta')}</a></div>
<svg viewBox="0 0 300 380" role="img" aria-label="Column"><g fill="none" stroke="#c9a24b" stroke-width="2"><path d="M40 40h220v24H40zM60 64h180v14H60zM80 78h140M96 78v240M120 78v240M150 78v240M180 78v240M204 78v240M60 318h180v14H60zM40 332h220v28H40z"/><circle cx="150" cy="20" r="10"/></g></svg></section>
<section><h2>${t('popular')}</h2><div class="grid">${P.slice(0,4).map(personCard).join('')}</div></section>
<section><h2>${t('great')}</h2><div class="grid">${E.filter(e=>['pyramids','rome','mongol','french'].includes(e.id)).map(eventCard).join('')}</div></section>
<section><div class="day"><h2>${t('day')}</h2><p>${exact?'':`<span class="meta">${t('nextDay')}: ${d[1]}.${String(d[0]).padStart(2,'0')}</span><br>`}${esc(L([d[2],d[3]]))}</p></div></section>
<section><h2>${t('facts')}</h2><ul>${rnd}</ul></section>`}

let F={q:'',cat:'',era:'',c:'',s:'name'};
function people(){const countries=[...new Set(P.map(p=>L(p.c)))].sort();
const opt=(o,cur)=>Object.entries(o).map(([k,v])=>`<option value="${k}"${cur===k?' selected':''}>${v}</option>`).join('');
return`<section class="fade"><h2>${t('people')}</h2><div class="tools">
<input id="q" type="search" placeholder="${t('search')}" value="${esc(F.q)}" aria-label="${t('search')}">
<select id="fc" aria-label="${t('cat')}"><option value="">${t('cat')}: ${t('all')}</option>${opt(UI[lang].cats,F.cat)}</select>
<select id="fe" aria-label="${t('era')}"><option value="">${t('era')}: ${t('all')}</option>${opt(UI[lang].eras,F.era)}</select>
<select id="fk" aria-label="${t('country')}"><option value="">${t('country')}: ${t('all')}</option>${countries.map(c=>`<option${F.c===c?' selected':''}>${esc(c)}</option>`).join('')}</select>
<select id="fs" aria-label="${t('sort')}"><option value="name">${t('byName')}</option><option value="year"${F.s==='year'?' selected':''}>${t('byYear')}</option></select>
<button id="rs">${t('reset')}</button></div><div id="res" class="grid"></div></section>`}
function filterPeople(){const q=F.q.trim().toLowerCase();
let r=P.filter(p=>(!F.cat||p.cat===F.cat)&&(!F.era||p.era===F.era)&&(!F.c||L(p.c)===F.c)&&(!q||[...p.n,...p.full,...p.c,p.kw,...p.bio].join(' ').toLowerCase().includes(q)));
r.sort((a,b)=>F.s==='year'?a.y-b.y:L(a.n).localeCompare(L(b.n),lang));
$('#res').innerHTML=r.length?r.map(personCard).join(''):`<p>${t('none')}</p>`}
function bindPeople(){const m={q:'q',fc:'cat',fe:'era',fk:'c',fs:'s'};
for(const id in m)$('#'+id).addEventListener(id==='q'?'input':'change',e=>{F[m[id]]=e.target.value;filterPeople()});
$('#rs').onclick=()=>{F={q:'',cat:'',era:'',c:'',s:'name'};route()};filterPeople()}

function person(id){const i=P.findIndex(x=>x.id===id);if(i<0)return nf();const p=P[i],x=X[id],pv=P[(i+P.length-1)%P.length],nx=P[(i+1)%P.length];
const rel=E.filter(e=>e.pp.includes(id)),facts=[...p.fun,...x.f];
return`<div class="wrap fade"><a href="#/people">${t('back')}</a><div class="person" style="margin-top:1rem"><aside class="side">${portrait(p)}
<dl class="dates"><dt>${t('born')}</dt><dd>${esc(L(p.dt).split(/ — | – /)[0])}</dd><dt>${t('died')}</dt><dd>${esc(L(p.dt).split(/ — | – /)[1]||'')}</dd><dt>${t('age')}</dt><dd>${esc(L(x.age))}</dd><dt>${t('active')}</dt><dd>${esc(L(x.act))}</dd></dl></aside><div>
<span class="tag">${esc(UI[lang].cats[p.cat])}</span><span class="tag">${esc(UI[lang].eras[p.era])}</span><h1>${esc(L(p.n))}</h1>
<p class="meta">${esc(L(p.full))} · ${esc(L(p.c))}</p>
<nav class="jump"><a href="#/person/${id}" data-s="s1">${t('bio')}</a><a href="#/person/${id}" data-s="s2">${t('life')}</a><a href="#/person/${id}" data-s="s3">${t('fun')}</a><a href="#/person/${id}" data-s="s4">${t('src')}</a></nav>
<h2 id="s1">${t('bio')}</h2><p>${esc(L(p.bio))}</p><h3>${t('bio2')}</h3>${x.b2.map(b=>`<p>${esc(L(b))}</p>`).join('')}
<h3>${t('ach')}</h3><ul>${p.ach.map(a=>`<li>${esc(L(a))}</li>`).join('')}</ul>
<h2 id="s2">${t('life')}</h2><ul class="tl">${p.tl.map(y=>`<li><b>${esc(L([y[0],y[1]]))}</b> — ${esc(L([y[2],y[3]]))}</li>`).join('')}</ul>
<h2 id="s3">${t('fun')}</h2><ul class="facts">${facts.map(f=>`<li>${esc(L(f))}</li>`).join('')}</ul>
${rel.length?`<h3>${t('events')}</h3><div class="grid">${rel.map(eventCard).join('')}</div>`:''}
<div id="s4">${srcList(p.src)}</div><p class="meta">${t('imgsrc')}</p>
<div class="pn"><a class="btn" href="#/person/${pv.id}">${t('prev')}</a><a class="btn" href="#/person/${nx.id}">${t('next')}</a></div></div></div></div>`}

function events(){return`<section class="fade"><h2>${t('events')}</h2><div class="grid">${E.map(eventCard).join('')}</div></section>`}
function event(id){const e=E.find(x=>x.id===id);if(!e)return nf();const ex=EX[id]||{m:['',''],f:[]};
return`<div class="wrap fade"><a href="#/events">${t('back')}</a>${evPic(e)}<h1 style="margin-top:1rem">${esc(L(e.n))}</h1><p class="meta">${t('date')}: ${esc(L(e.dt))}</p><p>${esc(L(e.d))}</p>${ex.m[0]?`<p>${esc(L(ex.m))}</p>`:''}
<h3>${t('causes')}</h3><p>${esc(L(e.ca))}</p><h3>${t('cons')}</h3><p>${esc(L(e.co))}</p>
${ex.f.length?`<h3>${t('fun')}</h3><ul class="facts">${ex.f.map(f=>`<li>${esc(L(f))}</li>`).join('')}</ul>`:''}${e.disp?`<div class="note"><b>${t('disp')}:</b> ${esc(L(e.disp))}</div>`:''}
${e.pp.length?`<h3>${t('rel')}</h3><div class="grid">${e.pp.map(i=>personCard(P.find(p=>p.id===i))).join('')}</div>`:''}${srcList(e.src)}</div>`}

let curP='ancient';
function timeline(){const list=E.filter(e=>e.p===curP);
return`<section class="fade"><h2>${t('timeline')}</h2><div class="periods" role="tablist">${PER.map(k=>`<button role="tab" data-p="${k}" class="${k===curP?'on':''}">${t('per')[k]||UI[lang].per[k]}</button>`).join('')}</div>
<h3>${UI[lang].per[curP]} <span class="meta">(${L(RANGE[curP])})</span></h3><ul class="tl">${list.map(e=>`<li><b>${esc(L(e.dt))}</b> — <a href="#/event/${e.id}">${esc(L(e.n))}</a><br>${esc(L(e.d))}</li>`).join('')}</ul></section>`}
const nf=()=>`<section><p>${t('notfound')}</p><a href="#/">${t('home')}</a></section>`;

/* ---------- router ---------- */
function route(){const h=location.hash.replace(/^#\/?/,'').split('/'),r=h[0]||'home';
app.innerHTML=r==='people'?people():r==='person'?person(h[1]):r==='events'?events():r==='event'?event(h[1]):r==='timeline'?timeline():r==='home'?home():nf();
if(r==='people')bindPeople();
document.querySelectorAll('[data-s]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.s).scrollIntoView({behavior:'smooth',block:'start'})});
document.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>{curP=b.dataset.p;route()});
$('#nav').innerHTML=[['home',''],['people','people'],['timeline','timeline'],['events','events']].map(([k,l])=>`<a href="#/${l}" class="${(r===l||(r==='home'&&!l)||(r==='person'&&l==='people')||(r==='event'&&l==='events'))?'on':''}">${t(k)}</a>`).join('');
$('#foot').textContent=t('foot');$('#lang').textContent=lang==='ru'?'EN':'RU';
document.documentElement.lang=lang;document.title='Chronos — Historical Encyclopedia';
if(!window._keep)window.scrollTo(0,0)}
$('#lang').onclick=()=>{lang=lang==='ru'?'en':'ru';localStorage.setItem('chronos-lang',lang);window._keep=1;route();window._keep=0};
window.addEventListener('hashchange',route);route();

const up=document.getElementById('up');up.onclick=()=>window.scrollTo({top:0,behavior:'smooth'});window.addEventListener('scroll',()=>up.classList.toggle('show',scrollY>500));
